window.kbPageData["views/entry/k-5c6f76b55ea1004a"] = {"key":"entry/k-5c6f76b55ea1004a","state":{"route":"entry/k-5c6f76b55ea1004a"},"node":{"id":"k-5c6f76b55ea1004a","mode":"k","title":"商品价值量","type":"原理与机制","domain":"经济","reading":"","intro":"","priority":100,"aliases":["商品经济理论 · 商品价值量"],"qs":["国考 2025 行政执法 行测#3"],"current":false,"candidates":false,"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"tags":{"主类":["原理与机制"],"出处性质":["理论手册"],"学科":["经济"],"来源主题":["马克思主义政治经济学"],"资料类别":["非时政"]},"seeAlso":["k-5fb7f91b7fbcdac6"],"directorySummary":"商品价值量是商品价值的大小，由生产该商品的社会必要劳动时间决定。社会必要劳动时间是在现有社会正常生产条件下，以社会平均劳动熟练程度和劳动强度生产某种使用价值所需的时间。","review":{"definition":"商品价值量是商品价值的大小，由生产该商品的社会必要劳动时间决定。社会必要劳动时间是在现有社会正常生产条件下，以社会平均劳动熟练程度和劳动强度生产某种使用价值所需的时间。","explanation":"同一种商品的生产者可能各有不同的实际耗时，商品价值量以社会通常生产条件下所需的劳动时间为准。第3题A项把决定因素写成个别劳动时间，因此错误。","references":[],"evidence":"由生产商品的社会必要劳动时间决定的","disposition":"独立词条","basis":"据原题和解析编释。"},"sources":[{"id":"14620c148b758944","label":"商品经济理论 · 商品价值量","topic":"马克思主义政治经济学","category":"非时政","text":"三、商品价值量\n商品的价值量是指商品价值的大小，是由社会必要劳动时间决定的。\n单位商品的价值量与生产该商品的社会必要劳动时间成正比，与社会劳动生产率成反比。","source":{"doc":"3ccc56f4000d1642c2d1","first":8,"last":8,"page":8,"file":"政治理论必学手册.pdf"},"basis":"理论手册"}]},"questions":{"国考 2025 行政执法 行测#3":{"paper":"国考 2025 行政执法 行测","n":3,"mod":"政治理论","src":["d8efe4e19862104d89c8.pdf",1],"asrc":["e2c4b1970d2b49eac0fd.pdf",1],"card":"336f02923851603a0b694fe9","links":[{"id":"k-5c6f76b55ea1004a","role":"解题依据","why":"判别商品价值量的决定因素，需要区分社会必要劳动时间和个别劳动时间。"}]}},"terms":{"k-5fb7f91b7fbcdac6":{"id":"k-5fb7f91b7fbcdac6","mode":"k","type":"概念与词义","title":"社会必要劳动时间","qs":[],"count":0}},"references":{},"topics":[],"units":{"k-5c6f76b55ea1004a":[["国考 2025 行政执法 行测#3"]]}};
